// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address adr) public {
        vm.assume(amount > 0 && adr != address(0) && adr != address(c) && adr != c.Owner());
        Reverter r = new Reverter();
        vm.deal(c.Owner(), amount);
        vm.prank(c.Owner());
        c.Command{value: amount}(address(r), hex"");
        assertTrue(address(c).balance == amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
